import os, time, uuid, logging
from flask import Flask, request, jsonify
import jwt, bcrypt, redis

BASE = '/app'
KEY_DIR = BASE + '/keys'
os.makedirs(BASE + '/logs', exist_ok=True)
logging.basicConfig(filename=BASE + '/logs/app.log', level=logging.INFO, format='%(asctime)s %(levelname)s api %(message)s')
log = logging.getLogger('api')

with open(KEY_DIR + '/private.pem') as f:
    PRIV = f.read()
with open(KEY_DIR + '/public.pem') as f:
    PUB = f.read()

ISS = 'rsa-jwt-api'
ACCESS_TTL = 15 * 60
REFRESH_TTL = 7 * 24 * 3600
rds = redis.Redis(host=os.environ.get('REDIS_HOST', 'localhost'), port=int(os.environ.get('REDIS_PORT', '6379')), decode_responses=True)
USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt()).decode()}

app = Flask(__name__)


def issue(sub, ttype, ttl):
    now = int(time.time())
    payload = {'iss': ISS, 'sub': sub, 'iat': now, 'exp': now + ttl, 'jti': str(uuid.uuid4()), 'type': ttype}
    return jwt.encode(payload, PRIV, algorithm='RS256')


def decode(token, verify_exp=True):
    return jwt.decode(token, PUB, algorithms=['RS256'], issuer=ISS,
                      options={'verify_exp': verify_exp, 'require': ['exp', 'iat', 'jti', 'sub', 'iss']})


def err(code, msg):
    log.warning('%s: %s', code, msg)
    return jsonify({'error': msg}), code


def bearer():
    h = request.headers.get('Authorization', '')
    if h.startswith('Bearer '):
        return h[7:]
    return None


def verify(token, expect_type=None):
    if not token:
        return None, err(401, 'missing token')
    try:
        claims = decode(token)
    except jwt.ExpiredSignatureError:
        return None, err(401, 'token expired')
    except jwt.InvalidTokenError as e:
        return None, err(401, 'invalid token: ' + str(e))
    if expect_type and claims.get('type') != expect_type:
        return None, err(401, 'wrong token type')
    if rds.exists('blacklist:' + claims['jti']):
        return None, err(403, 'token revoked')
    return claims, None


@app.route('/auth/public-key', methods=['GET'])
def public_key():
    return PUB, 200, {'Content-Type': 'text/plain'}


@app.route('/auth/login', methods=['POST'])
def login():
    body = request.get_json(silent=True) or {}
    u = str(body.get('username', ''))
    p = str(body.get('password', ''))
    h = USERS.get(u)
    if not h or not bcrypt.checkpw(p.encode(), h.encode()):
        return err(401, 'invalid credentials')
    log.info('login ok for %s', u)
    return jsonify({'access_token': issue(u, 'access', ACCESS_TTL),
                    'refresh_token': issue(u, 'refresh', REFRESH_TTL),
                    'token_type': 'Bearer',
                    'access_expires_in': ACCESS_TTL,
                    'refresh_expires_in': REFRESH_TTL}), 200


@app.route('/auth/refresh', methods=['POST'])
def refresh():
    body = request.get_json(silent=True) or {}
    claims, bad = verify(body.get('refresh_token'), 'refresh')
    if bad:
        return bad
    return jsonify({'access_token': issue(claims['sub'], 'access', ACCESS_TTL),
                    'token_type': 'Bearer', 'expires_in': ACCESS_TTL}), 200


@app.route('/auth/revoke', methods=['POST'])
def revoke():
    body = request.get_json(silent=True) or {}
    tok = body.get('token') or bearer()
    if not tok:
        return err(400, 'token required')
    try:
        claims = decode(tok, verify_exp=False)
    except jwt.InvalidTokenError as e:
        return err(401, 'invalid token: ' + str(e))
    ttl = max(int(claims['exp'] - time.time()), 1)
    rds.set('blacklist:' + claims['jti'], claims['sub'], ex=ttl)
    log.info('revoked jti %s', claims['jti'])
    return jsonify({'revoked': True, 'jti': claims['jti'], 'ttl': ttl}), 200


@app.route('/auth/validate', methods=['GET'])
def validate():
    claims, bad = verify(bearer() or request.args.get('token'))
    if bad:
        return bad
    return jsonify({'valid': True, 'sub': claims['sub'], 'jti': claims['jti'],
                    'type': claims['type'], 'exp': claims['exp']}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
