import sys, json, os, argparse, logging
import requests

TOKENS = '/app/tokens.json'
URL = os.environ.get('API_URL', 'http://localhost:5000')
os.makedirs('/app/logs', exist_ok=True)
logging.basicConfig(filename='/app/logs/app.log', level=logging.INFO, format='%(asctime)s %(levelname)s cli %(message)s')
log = logging.getLogger('cli')


def load():
    if not os.path.exists(TOKENS):
        return {}
    with open(TOKENS) as f:
        return json.load(f)


def save(d):
    with open(TOKENS, 'w') as f:
        json.dump(d, f, indent=2)


def fail(msg):
    log.error(msg)
    print('ERROR: ' + msg, file=sys.stderr)
    return 1


def call(method, path, token=None, body=None):
    headers = {'Authorization': 'Bearer ' + token} if token else {}
    return requests.request(method, URL + path, headers=headers, json=body, timeout=10)


def acquire(username, password):
    try:
        resp = requests.post(URL + '/auth/login', json={'username': username, 'password': password}, timeout=10)
    except requests.RequestException as e:
        return fail('login request failed: %s' % e)
    if resp.status_code != 200:
        return fail('login failed: %s %s' % (resp.status_code, resp.text))
    data = resp.json()
    save({'username': username, 'access_token': data['access_token'], 'refresh_token': data['refresh_token'],
          'revoked': {}})
    print('tokens acquired and saved to ' + TOKENS)
    return 0


def cmd_acquire(args):
    return acquire(args.username, args.password)


def cmd_validate(args):
    d = load()
    tok = d.get(args.kind + '_token')
    if not tok:
        return fail('no %s token found; run acquire' % args.kind)
    try:
        resp = call('GET', '/auth/validate', tok)
    except requests.RequestException as e:
        return fail('validate request failed: %s' % e)
    if resp.status_code == 200:
        print('valid: ' + json.dumps(resp.json()))
        return 0
    return fail('%s token rejected: %s %s' % (args.kind, resp.status_code, resp.text))


def cmd_revoke(args):
    d = load()
    tok = d.get(args.kind + '_token')
    if not tok:
        return fail('no %s token found; run acquire' % args.kind)
    try:
        resp = call('POST', '/auth/revoke', body={'token': tok})
    except requests.RequestException as e:
        return fail('revoke request failed: %s' % e)
    if resp.status_code != 200:
        return fail('revoke failed: %s %s' % (resp.status_code, resp.text))
    d.setdefault('revoked', {})[args.kind] = True
    save(d)
    print('%s token revoked: %s' % (args.kind, resp.json()))
    return 0


def cmd_retry(args):
    d = load()
    if d.get('access_token'):
        try:
            resp = call('GET', '/auth/validate', d['access_token'])
            if resp.status_code == 200:
                print('access token still valid; nothing to retry')
                return 0
        except requests.RequestException as e:
            return fail('validate request failed: %s' % e)
        log.warning('access token rejected (%s); attempting refresh' % resp.status_code)
    if d.get('refresh_token') and not d.get('revoked', {}).get('refresh'):
        try:
            resp = call('POST', '/auth/refresh', body={'refresh_token': d['refresh_token']})
            if resp.status_code == 200:
                d['access_token'] = resp.json()['access_token']
                save(d)
                print('access token refreshed')
                return 0
            log.warning('refresh failed: %s %s' % (resp.status_code, resp.text))
        except requests.RequestException as e:
            return fail('refresh request failed: %s' % e)
    print('refresh unavailable; acquiring new tokens')
    return acquire(d.get('username', 'admin'), args.password)


def main():
    p = argparse.ArgumentParser(description='JWT auth CLI')
    sub = p.add_subparsers(dest='cmd', required=True)
    a = sub.add_parser('acquire')
    a.add_argument('--username', default='admin')
    a.add_argument('--password', default='password123')
    a.set_defaults(func=cmd_acquire)
    v = sub.add_parser('validate')
    v.add_argument('--kind', choices=['access', 'refresh'], default='access')
    v.set_defaults(func=cmd_validate)
    r = sub.add_parser('revoke')
    r.add_argument('--kind', choices=['access', 'refresh'], default='access')
    r.set_defaults(func=cmd_revoke)
    t = sub.add_parser('retry')
    t.add_argument('--password', default='password123')
    t.set_defaults(func=cmd_retry)
    args = p.parse_args()
    sys.exit(args.func(args))


if __name__ == '__main__':
    main()
